/**
 * Smart Email Agent v3 — OpenClaw Bootstrap Hook
 * Inyecta estado de presupuesto, modo activo y learnings pendientes.
 */
const fs   = require('fs');
const path = require('path');
const WS   = path.join(process.env.HOME, '.openclaw', 'workspace');

function getBudgetInfo() {
  const f = path.join(WS, 'budget_tracker.json');
  try {
    if (!fs.existsSync(f)) return '⚠️  budget_tracker.json no encontrado. Ejecuta: python3 scripts/init_orchestrator.py';
    const d   = JSON.parse(fs.readFileSync(f, 'utf8'));
    const pct = Math.round(d.spent_usd / d.budget_usd * 100);
    const proj = (d.spent_usd / new Date().getDate() * 31).toFixed(3);
    let mode, model, restriction = null;
    if      (pct >= 95) { mode = '🔴 EMERGENCIA';    model = 'ninguno — cero IA';               restriction = 'CRITICO: No llamar a Anthropic API. Solo gog + reglas locales.'; }
    else if (pct >= 80) { mode = '🟠 AHORRO FUERTE'; model = 'claude-haiku-4-5-20251001 forzado'; restriction = 'ACTIVO: Solo Haiku. Sin borradores. Batch >= 20.'; }
    else if (pct >= 60) { mode = '🟡 AHORRO LEVE';   model = 'Haiku preferido';                 restriction = 'AVISO: Max 2 borradores/sesión.'; }
    else                { mode = '✅ NORMAL';          model = 'Haiku → clasificar | Sonnet → borradores prio≥8'; }
    const lines = [
      '## Smart Email Agent — Contexto',
      `Presupuesto: $${d.spent_usd.toFixed(3)} / $${d.budget_usd.toFixed(2)} (${pct}%) | Proyección: $${proj} | Mes: ${d.month}`,
      `Modo: ${mode} | Modelo: ${model}`,
    ];
    if (restriction) lines.push(`> ⚡ ${restriction}`);
    return lines.join('\n');
  } catch (e) { return `⚠️  Error leyendo presupuesto: ${e.message}`; }
}

function getPendingLearnings() {
  const f = path.join(WS, '.learnings', 'LEARNINGS.md');
  try {
    if (!fs.existsSync(f)) return null;
    const n = (fs.readFileSync(f, 'utf8').match(/\*\*Status\*\*: pending/g) || []).length;
    return n > 0 ? `Learnings pendientes: ${n} — revisar al cerrar sesión.` : null;
  } catch { return null; }
}

const handler = async (event) => {
  if (!event?.context || !Array.isArray(event.context.bootstrapFiles)) return;
  if (event.type !== 'agent' || event.action !== 'bootstrap') return;
  if ((event.sessionKey || '').includes(':subagent:')) return;

  const parts = [getBudgetInfo()];
  const l = getPendingLearnings();
  if (l) parts.push(l);
  parts.push('Lazy loading: NO cargar los 6 skills de email por separado. Este skill los fusiona todos.');

  event.context.bootstrapFiles.push({
    path: 'SMART_EMAIL_CTX.md',
    content: parts.join('\n'),
    virtual: true,
  });
};

module.exports = handler;
module.exports.default = handler;

#!/usr/bin/env python3
"""Smart Email Agent v3 — Setup inicial."""
import json, os, shutil, sys
from datetime import datetime
from pathlib import Path

WS = Path.home() / '.openclaw' / 'workspace'

def ok(m):   print(f"  ✅ {m}")
def warn(m): print(f"  ⚠️  {m}")
def err(m):  print(f"  ❌ {m}"); 

def check_prereqs():
    print("\n── Prerequisitos")
    if shutil.which('gog'): ok("gog CLI instalado")
    else: warn("gog no encontrado — instalar: npm i -g gogcli  o  brew install gogcli")
    gog_acc = os.environ.get('GOG_ACCOUNT')
    if gog_acc: ok(f"GOG_ACCOUNT = {gog_acc}")
    else: err("GOG_ACCOUNT no configurado — requerido"); return False
    if os.environ.get('ANTHROPIC_API_KEY'): ok("ANTHROPIC_API_KEY configurado")
    else: err("ANTHROPIC_API_KEY no configurado — requerido para análisis IA"); return False
    for k in ['EMAIL_BUDGET_USD', 'NOTIFY_CHANNEL', 'SAFE_BROWSING_API_KEY']:
        v = os.environ.get(k)
        if v: ok(f"{k} = {v}")
        else: warn(f"{k} no configurado (opcional)")
    return True

def init_budget():
    print("\n── Presupuesto")
    f = WS / 'budget_tracker.json'
    if f.exists():
        d = json.loads(f.read_text())
        pct = round(d['spent_usd'] / d['budget_usd'] * 100)
        ok(f"${d['spent_usd']:.3f} / ${d['budget_usd']:.2f} ({pct}%) — mes {d['month']}")
        return
    budget = float(os.environ.get('EMAIL_BUDGET_USD', '1.00'))
    f.write_text(json.dumps({
        "month": datetime.now().strftime('%Y-%m'),
        "budget_usd": budget, "spent_usd": 0.0,
        "alert_at_pct": [60, 80, 95], "sessions": []
    }, indent=2))
    ok(f"Inicializado: ${budget:.2f}/mes")

def init_learnings():
    print("\n── Learnings")
    d = WS / '.learnings'
    d.mkdir(exist_ok=True)
    for fn in ['LEARNINGS.md', 'ERRORS.md']:
        fp = d / fn
        if not fp.exists():
            fp.write_text(f"# {fn.replace('.md','')}\n\n")
            ok(f"Creado: .learnings/{fn}")
        else:
            n = fp.read_text().count('**Status**: pending')
            ok(f".learnings/{fn} — {n} pendientes")

def check_gog_auth():
    print("\n── Autenticación Gmail")
    import subprocess
    r = subprocess.run(['gog', 'auth', 'status'], capture_output=True, text=True)
    if r.returncode == 0: ok(f"Autenticado: {r.stdout.strip()}")
    else: warn(f"No autenticado — ejecutar: gog auth add {os.environ.get('GOG_ACCOUNT', 'tu@gmail.com')}")

if __name__ == '__main__':
    print("═══════════════════════════════════════")
    print("  Smart Email Agent v3 — Setup Inicial")
    print("═══════════════════════════════════════")
    if not check_prereqs(): sys.exit(1)
    init_budget()
    init_learnings()
    check_gog_auth()
    print("\n✅ Listo.")
    print("   Activar hook: openclaw hooks enable smart-email-agent\n")
